#include <iiMultimodalAgent/agent/Rag.h>
namespace agent = iiMultimodalAgent::agent;

auto index = std::make_shared<agent::KnowledgeIndex>(privateStorePath);
index->upsert({"creator/canvas-42", "Canvas project", "society://canvas/42",
    "rev-7", "document", {{"canvas:42/note:original", "Original artwork is preserved."}}});

// model은 호스트가 소유한 agent::Model 구현 또는 iiLocalLLM ServiceModel이다.
agent::Rag rag(index, model);
auto result = rag.answer("Where is the original artwork?", modelName);
// result.status, result.text, result.evidence를 함께 확인한다.

// authorize는 호스트의 세션 및 테넌트 소유권을 매번 검사한다.
options.additionalTools.append(agent::knowledgeSearchTool(index, workspace, authorize));
```

