#include <iiMultimodalAgent/agent/SemanticRag.h>
auto embedder = std::make_shared<agent::LocalEmbeddingProvider>(service,
    agent::LocalEmbeddingOptions{"model://embedding-model", "query: ", "passage: "});
auto semantic = std::make_shared<agent::SemanticKnowledgeIndex>(index, embedder, privateVectorPath);
semantic->refresh(); // 자료 또는 모델 변경 시 호스트가 다시 호출한다.
